import { Component } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Application } from 'src/app/auth/Models/Application';
import { Company } from 'src/app/landing/models/company';
import { Job } from 'src/app/landing/models/job';
import { ApplicationService } from 'src/app/service/application/application.service';
import { CompanyService } from 'src/app/service/company/company.service';
import { SeekerService } from 'src/app/service/seeker/seeker.service';

@Component({
  selector: 'app-edit-profile',
  templateUrl: './edit-profile.component.html',
  styleUrls: ['./edit-profile.component.css']
})
export class EditProfileComponent {

    isLoggedIn = false;
    initials = '';
    profileRoute = '/';

    companyId!: number;

    company!: Company;
    jobs: Job[] = [];
    applications: Application[] = [];
    pendingApplications: Application[] = [];
    approvedAppplications: Application[] = [];

    constructor(
      private compService: CompanyService,
      private appService: ApplicationService,
      private router: Router,
      private route: ActivatedRoute,
      private jobSeekerService: SeekerService
    ) {}

    ngOnInit(): void {

    const routeId = this.route.snapshot.paramMap.get('id');

    if (routeId) {
      // Public company profile
      this.companyId = Number(routeId);
    } else {
      // Logged-in company profile
      this.companyId = Number(localStorage.getItem('id'));
    }

    this.isLoggedIn = !!localStorage.getItem('token');

    if (this.isLoggedIn) {

      const role = localStorage.getItem('role');
      const loginId = Number(localStorage.getItem('id'));

      if (role === 'COMPANY') {

        this.profileRoute = '/company-dashboard';

        this.compService.getCompanyById(loginId).subscribe({
          next: (company: any) => {
            if (company?.companyName) {
              this.initials = company.companyName
                .split(' ')
                .map((x: string) => x.charAt(0))
                .join('')
                .substring(0, 2)
                .toUpperCase();
            }
          }
        });

      } else {

        this.profileRoute = '/jobseeker-dashboard';

        this.jobSeekerService.getSeekerById(loginId).subscribe({
          next: (user: any) => {

            const name =
              user.userName ??
              `${user.firstName ?? ''} ${user.lastName ?? ''}`.trim();

            if (name) {
              this.initials = name
                .split(' ')
                .map((x: string) => x.charAt(0))
                .join('')
                .substring(0, 2)
                .toUpperCase();
            }
          }
        });
      }
    }

    this.getCompanyById();
    this.getJobsByCompany();
  }
    getCompanyById() {
      this.compService.getCompanyById(this.companyId).subscribe(
        res => this.company = res
      );
    }

    getJobsByCompany() {
      this.compService.getJobsByCompany(this.companyId).subscribe(
        res => this.jobs = res
      );
    }

    getApplicantsByCompany() {
      this.appService.getApplicantsByCompany(this.companyId).subscribe(
        res => this.applications = res
      );
    }

    getPendingApplications() {
      this.appService.getPendindApplicants(this.companyId).subscribe(
        res => this.pendingApplications = res
      );
    }

    getHiredApplicants() {
      this.appService.getHiredApplicants(this.companyId).subscribe(
        res => this.approvedAppplications = res
      );
    }

    logout(): void {
      localStorage.clear();
      this.router.navigate(['/']);
      alert('Continue to Logout?');
    }


}
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Edit Company Profile · HireHub</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap" rel="stylesheet">

<header class="topnav app">
  <div class="wrap">
    <a routerLink="/" class="brand"><span class="brand-dot"></span>HireHub</a>
    <nav class="nav-links app-links">
      <a routerLink="/company-dashboard">Dashboard</a>
      <a routerLink="/company-post-job">Post a Job</a>
      <a routerLink="/company-manage-jobs">Manage Jobs</a>
      <a routerLink="/company-applicants">Applicants</a>
      <a routerLink="/profile-company">Company Profile</a>
    </nav>
    <div class="nav-actions">
     <div class="avatar" *ngIf="company?.companyName">
  {{ company.companyName.charAt(0) }}{{ company.companyName.split(' ')[1]?.charAt(0) || '' }}
</div>

      <button class="btn btn-ghost-dark btn-sm" (click)="logout()">
        Logout
      </button>
    </div>

  </div>
</header>
<div class="app-shell">
<aside class="sidebar">
  <div class="sidebar-group">
    <span class="sidebar-label">General</span>
    <a href="company-dashboard.html"><span class="dot"></span>Dashboard</a>
    <a href="company-profile.html" class="active"><span class="dot"></span>Company Profile</a>
  </div>
  <div class="sidebar-group">
    <span class="sidebar-label">Hiring</span>
    <a href="company-post-job.html"><span class="dot"></span>Post a Job</a>
    <a href="company-manage-jobs.html"><span class="dot"></span>Manage Jobs</a>
    <a href="company-applicants.html"><span class="dot"></span>Applicants</a>
  </div>
</aside>
<main class="main">

<div class="page-title">Edit Company Profile</div>
<div class="form-card">
  <div class="field"><label>Company name</label><input value="Nimbus Cloud"></div>
  <div class="field"><label>Email</label><input value="hr@nimbuscloud.io"></div>
  <div class="field"><label>Website</label><input value="nimbuscloud.io"></div>
  <div class="field"><label>Location</label><input value="Kochi, IN"></div>
  <div class="field"><label>Description</label><textarea>Cloud infrastructure tooling for mid-market SaaS teams.</textarea></div>
  <div class="form-actions">
    <a href="company-profile.html" class="btn btn-primary">Save changes</a>
    <a href="company-profile.html" class="btn btn-secondary">Cancel</a>
  </div>
</div>

</main>
</div>
